 1	method Deli(a: array<char>, i: nat)
 2	modifies a
 3	requires a.Length > 0
 4	requires 0 <= i < (a.Length) + 1
 5	ensures forall j :: 0 <= j < i ==> a[j] == old(a[j])
 6	ensures forall j :: i <= j < a.Length - 1 ==> a[j] == old(a[j + 1])
 7	ensures a[a.Length - 1] == '.'
 8	{
 9		var c := i;
10		while c < a.Length - 1
11		invariant i <= c <= a.Length - 1
12		invariant forall j :: i <= j < c ==> a[j] == old(a[j + 1])
13		// unchanged first half
14		invariant forall j :: 0 <= j < i ==> a[j] == old(a[j])
15		invariant forall j :: c <= j < a.Length ==> a[j] == old(a[j])
16		{
17			a[c] := a[c + 1];
18			c := c + 1;
19		}
20		a[c] := '.';
21	}
22	
23	method DeliChecker()
24	{
25	   var z := new char[]['b','r','o','o','m'];
26	   Deli(z, 1);
27	   assert z[..] == "boom.";
28	   Deli(z, 3);
29	   assert z[..] == "boo..";
30	   Deli(z, 4);
31	   assert z[..] == "boo..";
32	   Deli(z, 3);
33	   assert z[..] == "boo..";
34	   Deli(z, 0);
35	   Deli(z, 0);
36	   Deli(z, 0);
37	   assert z[..] == ".....";
38	
39	   z := new char[]['x'];
40	   Deli(z, 0);
41	   assert z[..] == ".";
42	}
43

